async function forceOneMoreAdventureRoute(start,required,minKm,maxKm,effectiveMax,minimumReturn,token){const attempts=[];for(let i=0;i<8;i++){const seed=S.routes.length*11+i,target=minKm+(maxKm-minKm)*(.22+(i%6)*.13),bearing=(23+seed*137.508)%360,count=3+(i%3),radius=Math.max(1.1,target/(2*Math.PI)*(.56+(i%4)*.08)),ring=[...required];for(let n=0;n<count;n++)ring.push(turf.destination(start,radius,bearing+n*360/count).geometry.coordinates);attempts.push({profile:i%3===0?'balanced':i%3===1?'scenic':'established',target,points:[start,...ring,start],places:[],forceFallback:true})}for(const plan of attempts){if(token!==adventureBuildToken)return null;const routes=await fastDirections(plan.points,5600,false).catch(()=>[]);for(const raw of routes){if(!validateAdventureLoop(raw,start).valid||hasMotorway(raw))continue;const route=closeAdventureGeometry(raw,start),quick=quickAdventureQuality(route.geometry.coordinates,Math.max(.1,(route.distance||0)/1000)),candidate=scoreAdventureCandidateFast(route,plan.target,minKm,Math.max(effectiveMax,maxKm*1.35),minimumReturn,{waypointEfficient:required.length>0},quick);if(!candidate?.route)continue;route._requestPoints=plan.points;route.adventureProfile=plan.profile;route.adventureCompromise='Unfiltered extra';route.qualityLabel='Extra route · quality filters relaxed';route.rangeStatus=(route.distance||0)/1000<=maxKm?'Within selected range':`${Math.max(0,(route.distance||0)/1000-maxKm).toFixed(1)} km over maximum`;route.recommended=false;return route}}return null}
