function scoreAdventureCandidate(route,target,minKm,effectiveMax,minimumLoop,context={}){if(!route)return null;const q=quickAdventureQuality(route.geometry.coordinates,target),safety=routeSafetyAndDirectness(route);if(!safety.safe)return null;route._quickQualityScore=q.score;route.retrace=q.retrace;route.overlapKm=q.overlapKm;route.compactness=q.compactness;route.deadEndKm=q.deadEndKm;const routeKm=(route.distance||0)/1000,rangeOverflow=Math.max(0,routeKm-effectiveMax),rangeUnder=Math.max(0,minKm-routeKm);const waypointEfficient=!!context.waypointEfficient,repetitionPenalty=waypointEfficient?Math.min(q.retrace*35+q.deadEndKm*4,q.retrace*280+q.deadEndKm*38):q.retrace*280+q.deadEndKm*38;route.routePenalty=safety.penalty;route.rangeOverflow=rangeOverflow;route.waypointEfficient=waypointEfficient;route.loopQuality=100-repetitionPenalty-safety.penalty-rangeOverflow*24-rangeUnder*10;route.unnecessaryCrossings=safety.crossingPenalty;const within=route.distance/1000>=Math.min(minKm,Math.max(1,minimumLoop*.82))&&route.distance/1000<=effectiveMax*1.32,recommended=q.closed&&within&&(waypointEfficient||(q.retrace<=.13&&q.deadEndKm<=.35&&q.compactness>=.15));route.recommended=recommended;route.qualityLabel=waypointEfficient?'Efficient waypoint return':recommended?'Recommended':rangeOverflow>0?`Best available · ${rangeOverflow.toFixed(1)} km over range`:'Best available';route.cycleScore=cycleScore(route);route.osmCycleScore=null;route.cycleScorePending=true;route.name='Adventure route';return{route,recommended}}
