async function buildShorterAdventureCandidates(start,required,minKm,maxKm,minimumLoop){const floor=Math.max(minKm,minimumLoop*1.04),targets=[Math.min(maxKm,floor),Math.min(maxKm,Math.max(floor,minKm+(maxKm-minKm)*.25)),Math.min(maxKm,Math.max(floor,minKm+(maxKm-minKm)*.5))],bearings=[30,150,270],jobs=[];for(let i=0;i<targets.length;i++){const target=Math.max(3,targets[i]),radius=Math.max(1.2,target/(2*Math.PI)*.72),anchors=buildAdventureAnchors(start,required,radius,bearings[i],50+i);jobs.push(directions(anchors,false).then(routes=>scoreAdventureCandidate(routes[0],target,minKm,maxKm,minimumLoop)).catch(()=>null))}return(await Promise.all(jobs)).filter(Boolean)}
