function prepareImmediateRouteMetrics(route){route.cycleScore=Number.isFinite(route.cycleScore)?route.cycleScore:cycleScore(route);route.osmCycleScore=Number.isFinite(route.osmCycleScore)?route.osmCycleScore:null;route.cycleScorePending=route.osmCycleScore===null;route.elev=Array.isArray(route.elev)?route.elev:[];route.wind=Array.isArray(route.wind)?route.wind:[];route.ascent=Number.isFinite(route.ascent)?route.ascent:null;return route}
function publishAdventureRoutes(routes,append=false){if(S.mode==='loop'&&S.waypoints[0])routes=routes.filter(r=>validateAdventureLoop(r,S.waypoints[0]).valid).map(r=>closeAdventureGeometry(r,S.waypoints[0]));routes.forEach(prepareImmediateRouteMetrics);S.routes=append?[...S.routes,...routes]:routes;S.routes=append?S.routes:S.routes.sort((a,b)=>(b.loopQuality||0)-(a.loopQuality||0));S.routes.forEach((r,i)=>r.name=`Adventure ${i+1}`);S.selected=null;S.route=null;drawAll();cards();stars();updateQuickNav()}
async function enrichAdventureCards(routes,token){for(const route of routes){if(token!==adventureBuildToken)return;await enrich(route);if(token!==adventureBuildToken)return;prepareImmediateRouteMetrics(route);cards();await new Promise(resolve=>setTimeout(resolve,60))}}
function buildAdventureAnchors(start,required,radius,bearing,seed){const centre=turf.destination(start,radius*.22,bearing+180).geometry.coordinates,shape=[];for(let k=0;k<5;k++){const angle=bearing+k*72+(seed%3-1)*8,scale=k%2?1.04:.9;shape.push(turf.destination(centre,radius*scale,angle).geometry.coordinates)}const all=[...required,...shape],angle=p=>(turf.bearing(centre,p)+360)%360;all.sort((a,b)=>angle(a)-angle(b));const startAngle=angle(start),pivot=all.findIndex(p=>angle(p)>=startAngle),ordered=pivot<0?all:[...all.slice(pivot),...all.slice(0,pivot)];return dedupeViaPoints([start,...ordered,start])}
