function analyseAdventureLoop(coords,start,targetKm,route=null){if(!coords?.length)return{closed:false,retrace:1,overlapKm:Infinity,compactness:0,deadEndKm:Infinity,score:-999};const line=turf.lineString(coords),length=turf.length(line),closed=turf.distance(coords[0],coords.at(-1))<.12,spacing=.08,samples=[];for(let d=0;d<=length;d+=spacing)samples.push({d,p:turf.along(line,d).geometry.coordinates});let overlap=0,longestOverlap=0,currentOverlap=0;for(let i=0;i<samples.length;i++){let duplicated=false;for(let j=0;j<i-7;j++){if(Math.abs(samples[i].d-samples[j].d)<.7)continue;if(turf.distance(samples[i].p,samples[j].p,{units:'kilometers'})<.075){duplicated=true;break}}if(duplicated){overlap+=spacing;currentOverlap+=spacing;longestOverlap=Math.max(longestOverlap,currentOverlap)}else currentOverlap=0}const deadEndKm=Math.max(longestOverlap,detectRouteSpurs(coords,route)),retrace=Math.min(1,overlap/Math.max(.1,length)),bbox=turf.bbox(line),diag=turf.distance([bbox[0],bbox[1]],[bbox[2],bbox[3]]),compactness=Math.min(1,diag/Math.max(1,length)*2.2),distancePenalty=Math.abs(length-targetKm)/Math.max(5,targetKm),score=(closed?100:0)-retrace*280-deadEndKm*38+compactness*35-distancePenalty*24;return{closed,retrace,overlapKm:overlap,compactness,deadEndKm,score}}
