async function directions(p,alternatives){try{const c=p.map(x=>x.join(',')).join(';'),d=await fetch(`https://api.mapbox.com/directions/v5/mapbox/cycling/${c}?alternatives=${alternatives}&geometries=geojson&overview=full&steps=true&access_token=${MAPBOX_TOKEN}`).then(r=>r.json());return d.routes||[]}catch{return[]}}
async function findPOI(p,pref,i){const qs={mixed:['viewpoint','landmark','cafe'],scenic:['viewpoint','country park','nature reserve'],landmark:['castle','monument','landmark'],food:['cafe','bakery','restaurant'],cycle:['national cycle route','cycle trail','greenway']}[pref],q=qs[i%qs.length];try{const d=await fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${encodeURIComponent(q)}.json?types=poi&proximity=${p}&limit=5&access_token=${MAPBOX_TOKEN}`).then(r=>r.json()),f=d.features?.[0];return f?{name:f.text,center:f.center}:null}catch{return null}}
async function accept(rs,append){rs=rs.filter(Boolean);await Promise.all(rs.map(enrich));rs.forEach(r=>r.cycleScore=cycleScore(r));rs.sort((a,b)=>b.cycleScore-a.cycleScore);S.routes=append?[...S.routes,...rs]:rs;S.selected=null;S.route=null;drawAll();cards();stars();updateQuickNav()}
async function enrich(r){prepareImmediateRouteMetrics(r);const points=sample(r.geometry.coordinates,24);try{const d=await fetch(`https://api.open-meteo.com/v1/elevation?latitude=${points.map(x=>x[1])}&longitude=${points.map(x=>x[0])}`).then(r=>r.json());r.elev=d.elevation||[];r.ascent=gain(r.elev)}catch{r.elev=[];r.ascent=0}try{const now=Date.now(),forecastPoints=points.slice(0,12).map((p,i)=>({lat:p[1],lon:p[0],time:new Date(now+(r.duration||3600)*1000*i/11)})),weather=await fetchRouteForecast(forecastPoints);r.wind=weather.map((w,i)=>{const a=points[Math.min(i,points.length-2)],b=points[Math.min(i+1,points.length-1)],routeBearing=turf.bearing(a,b),windTo=(w.bearing+180)%360,component=w.speed*3.6*Math.cos((windTo-routeBearing)*Math.PI/180);return Math.round(component*10)/10});r.windSource=weather[0]?.source||'live weather'}catch{r.wind=[];r.windSource='unavailable'}const fallbackCycle=cycleScore(r);r.cycleScore=fallbackCycle;r.osmCycleScore=null;r.cycleScorePending=false;r.elev=Array.isArray(r.elev)?r.elev:[];r.wind=Array.isArray(r.wind)?r.wind:[]}
function fetchCycleInfrastructureScore(coords){return Promise.resolve(0)}

function cycleScore(r){let d=0,t=r.distance||1;(r.legs||[]).forEach(l=>(l.steps||[]).forEach(s=>{const text=`${s.name||''} ${s.ref||''}`.toLowerCase();if(/cycle|ncn|greenway|trail|towpath|shared path/.test(text))d+=s.distance||0}));return Math.round(100*d/t)}function sample(c,n){if(c.length<=n)return c;const l=turf.lineString(c),d=turf.length(l);return Array.from({length:n},(_,i)=>turf.along(l,d*i/(n-1)).geometry.coordinates)}
const colors=['#176bdb','#e34f4f','#139b66','#f28b30','#8b5bd6','#00a6a6'];function drawAll(){S.nodes.forEach(m=>m.remove());S.nodes=[];clearLines();S.routes.forEach((r,i)=>line(`r${i}`,r.geometry,colors[i%colors.length],i?5:7));if(S.routes.length){const f={type:'FeatureCollection',features:S.routes.map(r=>({type:'Feature',geometry:r.geometry,properties:{}}))},b=turf.bbox(f);map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:mobile()?45:{left:560,right:45,top:45,bottom:45}})}}function line(id,g,c,w){map.addSource(id,{type:'geojson',data:{type:'Feature',geometry:g,properties:{routeIndex:id.startsWith('r')?Number(id.slice(1)):S.selected}}});map.addLayer({id,type:'line',source:id,layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':c,'line-width':w,'line-opacity':.9}});S.layers.push(id);addRouteDirectionArrows(id,c,w);if(id.startsWith('r'))bindMapRouteSelection(id,Number(id.slice(1)))}function ensureRouteArrowImage(id,color){if(map.hasImage(id))return;const size=48,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const x=canvas.getContext('2d');x.translate(size/2,size/2);x.fillStyle=color;x.strokeStyle='#fff';x.lineWidth=5;x.lineJoin='round';x.beginPath();x.moveTo(-15,-12);x.lineTo(14,0);x.lineTo(-15,12);x.lineTo(-8,0);x.closePath();x.stroke();x.fill();map.addImage(id,x.getImageData(0,0,size,size),{pixelRatio:2})}
function addRouteDirectionArrows(sourceId,color,width){const layerId=`${sourceId}-direction`,imageId=`route-arrow-${color.replace('#','')}`;if(map.getLayer(layerId))map.removeLayer(layerId);ensureRouteArrowImage(imageId,color);map.addLayer({id:layerId,type:'symbol',source:sourceId,layout:{'symbol-placement':'line','symbol-spacing':width>=8?90:130,'icon-image':imageId,'icon-size':width>=8?.65:.48,'icon-allow-overlap':true,'icon-ignore-placement':true,'icon-rotation-alignment':'map'},paint:{'icon-opacity':width>=8?.95:.62}});S.layers.push(layerId)}
function clearLines(){const ids=[...new Set(S.layers)];ids.forEach(id=>{if(map.getLayer(id))map.removeLayer(id)});ids.forEach(id=>{if(map.getSource(id))map.removeSource(id)});S.layers=[];S.nodes.forEach(marker=>marker.remove());S.nodes=[]}

function bindMapRouteSelection(layerId,index){map.on('mouseenter',layerId,()=>{map.getCanvas().style.cursor='pointer';setRouteHover(layerId,true)});map.on('mouseleave',layerId,()=>{map.getCanvas().style.cursor='';setRouteHover(layerId,false)});map.on('click',layerId,e=>{e.originalEvent?.preventDefault?.();selectRouteFromMap(index)})}
function setRouteHover(layerId,on){if(!map.getLayer(layerId))return;map.setPaintProperty(layerId,'line-width',on?9:(layerId==='r0'?7:5));map.setPaintProperty(layerId,'line-opacity',on?1:.9)}
function selectRouteFromMap(index){if(!Number.isInteger(index)||!S.routes[index])return;select(index);open('explore');toast(`Route ${index+1} selected. Press Navigation and record now to begin.`);const b=$('#quick-nav');if(b&&!b.hidden)b.animate([{transform:'scale(.97)'},{transform:'scale(1.03)'},{transform:'scale(1)'}],{duration:420})}
function cards(){const x=$('#cards');if(!x)return;if(!S.routes.length){x.innerHTML='<div class="empty">Routes will appear here.</div>';return}x.innerHTML=S.routes.map((r,i)=>`<div class="card route ${S.selected===i?'selected':''}" data-i="${i}" style="--route-color:${colors[i%colors.length]};border-left:7px solid ${colors[i%colors.length]}"><div class="row"><b>${i?'Option '+(i+1):'Recommended'}</b><div class="card-icon-actions">${S.editingSavedId&&i===S.selected?`<button data-update-saved="${i}" title="Update saved route">✓</button>`:''}<button data-save-route="${i}" title="Save route as a copy">▣</button><button data-share-route="${i}" title="Share route">↗</button><button data-preview-route="${i}" title="Animate route preview">▶</button></div></div><span class="pill ${r.recommended===false?'route-compromise':''}">${r.qualityLabel?`${r.qualityLabel} · `:''}${Number.isFinite(r.cycleScore)?r.cycleScore:0}% cycle-route cues${r.cycleScorePending?' · refining…':''}${r.rangeStatus?` · ${r.rangeStatus}`:''}${r.waypointEfficient?' · repeated access accepted to minimise distance':Number.isFinite(r.retrace)?` · ${Math.round((1-r.retrace)*100)}% non-repeated`:''}</span><div class="stats"><div class="stat"><b>${fmt(r.distance/1000)}</b><small>km</small></div><div class="stat"><b>${Math.round(r.duration/60)}</b><small>min</small></div><div class="stat"><b>${Number.isFinite(r.ascent)?Math.round(r.ascent):'…'}</b><small>${Number.isFinite(r.ascent)?'climb m':'climb loading'}</small></div><div class="stat"><b>${Number.isFinite(r.osmCycleScore)?r.osmCycleScore:(Number.isFinite(r.cycleScore)?r.cycleScore:0)}%</b><small>${Number.isFinite(r.osmCycleScore)?'OSM cycle infra':'cycle-route estimate'}</small></div></div><div class="profiles"><div><div class="label">Elevation (m)</div>${r.elev?.length?`<canvas class="chart" data-e="${i}"></canvas>`:'<div class="profile-pending"><span class="mini-spinner"></span>Loading elevation</div>'}</div><div><div class="label">Tailwind + / headwind − (km/h)</div>${r.wind?.length?`<canvas class="chart" data-w="${i}"></canvas>`:'<div class="profile-pending"><span class="mini-spinner"></span>Loading live wind</div>'}</div></div>${S.mode==='loop'?`<button class="btn green card-navigate" data-nav-route="${i}">Navigate adventure route</button>`:''}</div>`).join('');x.onclick=e=>{const updateSaved=e.target.closest('[data-update-saved]'),save=e.target.closest('[data-save-route]'),share=e.target.closest('[data-share-route]'),preview=e.target.closest('[data-preview-route]'),nav=e.target.closest('[data-nav-route]'),card=e.target.closest('[data-i]');if(updateSaved){e.stopPropagation();saveEditedSavedRoute();return}if(save){e.stopPropagation();saveRouteByIndex(+save.dataset.saveRoute);return}if(share){e.stopPropagation();shareRouteByIndex(+share.dataset.shareRoute);return}if(preview){e.stopPropagation();select(+preview.dataset.previewRoute);previewRoute3D();return}if(nav){e.stopPropagation();select(+nav.dataset.navRoute);startNavigation();return}if(card)select(+card.dataset.i)};requestAnimationFrame(drawCharts)}
function showAllRoutesOnMap(){S.selected=null;S.route=null;drawAll();cards();updateQuickNav()}
function requireAccount(action='use this feature'){if(S.user)return true;toast(`Sign in to ${action}`);S.page='profile';document.body.classList.add('panel-open');render();return false}
function accountCacheKey(kind){return S.user?`account-${S.user.uid}-${kind}`:null}
function accountCollection(kind){return`users/${S.user.uid}/${kind}`}
function cacheAccountData(kind,items){if(!S.user)return;localStorage.setItem(accountCacheKey(kind),JSON.stringify(items));if(kind==='routes')S.accountRoutes=items;else S.accountActivities=items}
function loadAccountCache(kind){if(!S.user)return[];try{return JSON.parse(localStorage.getItem(accountCacheKey(kind)))||[]}catch{return[]}}
async function syncAccountLibrary(){if(!S.user||S.accountSyncing)return;S.accountSyncing=true;S.accountRoutes=loadAccountCache('routes');S.accountActivities=loadAccountCache('activities');try{const db=await getCloud(),load=async kind=>{const snap=await db.getDocs(db.collection(db.firestore,accountCollection(kind))),items=snap.docs.map(doc=>decodeAccountDocument(doc.id,doc.data())).filter(Boolean);cacheAccountData(kind,items);return items};await Promise.all([load('routes'),load('activities')]);if(S.page==='routes')routes();if(S.page==='record')record()}catch(error){console.warn('Account library sync unavailable; using account cache',error)}finally{S.accountSyncing=false}}
function encodeAccountDocument(kind,item){return{ownerId:S.user.uid,kind,name:item.name||'',createdAt:item.createdAt||item.importedAt||Date.now(),updatedAt:item.updatedAt||Date.now(),payloadJson:JSON.stringify(item)}}function decodeAccountDocument(id,data){try{const item=data?.payloadJson?JSON.parse(data.payloadJson):data;return{id,...item,id}}catch(error){console.warn('Invalid account document',id,error);return null}}
async function putAccountItem(kind,item){if(!requireAccount(`save ${kind==='routes'?'routes':'activities'}`))throw new Error('Sign-in required');const items=kind==='routes'?S.accountRoutes:S.accountActivities,index=items.findIndex(x=>x.id===item.id),next={...item,ownerId:S.user.uid,updatedAt:Date.now()};if(index>=0)items[index]=next;else items.unshift(next);cacheAccountData(kind,items);try{const db=await getCloud();await db.setDoc(db.doc(db.firestore,accountCollection(kind),next.id),encodeAccountDocument(kind,next))}catch(error){console.warn(`Cloud ${kind} save queued locally`,error)}return next}
async function deleteAccountItem(kind,id){if(!requireAccount('manage account data'))return;const items=(kind==='routes'?S.accountRoutes:S.accountActivities).filter(x=>x.id!==id);cacheAccountData(kind,items);try{const db=await getCloud();await db.deleteDoc(db.doc(db.firestore,accountCollection(kind),id))}catch(error){console.warn(`Cloud ${kind} delete queued locally`,error)}}
async function previewRoute3D(){if(!S.route)return toast('Select one route first');open('explore');setTimeout(()=>{const run=++S.previewRun,coords=sample(S.route.geometry.coordinates,Math.min(80,S.route.geometry.coordinates.length));if(coords.length<2)return toast('Route is too short to animate');let i=0;document.body.classList.add('route-previewing');toast('3D route preview started');const step=()=>{if(run!==S.previewRun||i>=coords.length-1){document.body.classList.remove('route-previewing');if(i>=coords.length-1)toast('3D preview complete');return}map.easeTo({center:coords[i],bearing:turf.bearing(coords[i],coords[i+1]),pitch:68,zoom:16.8,duration:520,essential:true});i++;setTimeout(step,550)};step()},80)}
async function saveRouteByIndex(i){if(!requireAccount('save routes'))return;const route=S.routes[i];if(!route)return;if(!Array.isArray(route.requiredNavigationWaypoints))route.requiredNavigationWaypoints=navigationWaypointSequence();const name=prompt('Route name',S.mode==='loop'?`${S.names[0]||'Adventure'} loop`:`${S.names[0]||'Start'} to ${S.names.at(-1)||'Finish'}`);if(!name?.trim())return;await putAccountItem('routes',{id:crypto.randomUUID(),name:name.trim(),route:structuredClone(route),names:structuredClone(S.names),waypoints:structuredClone(S.waypoints),mode:S.mode,createdAt:Date.now()});toast('Route saved to your account')}
async function renameSavedRoute(saved,index){if(!requireAccount('rename routes'))return;const item=saved[index];if(!item)return;const name=prompt('Rename saved route',item.name||'Saved route');if(!name?.trim()||name.trim()===item.name)return;item.name=name.trim();await putAccountItem('routes',item);toast('Account route renamed');routes()}
async function saveEditedSavedRoute(){if(!requireAccount('update routes'))return;if(!S.editingSavedId||!S.route)return toast('Open a saved route first');const item=S.accountRoutes.find(x=>x.id===S.editingSavedId);if(!item)return toast('Saved route could not be found');await putAccountItem('routes',{...item,route:structuredClone(S.route),waypoints:structuredClone(S.waypoints),names:structuredClone(S.names),mode:S.mode});toast('Saved route updated on your account')}
function pushRouteUndo(){if(S.route&&S.selected!==null){S.routeUndo.push({route:structuredClone(S.route),index:S.selected});if(S.routeUndo.length>10)S.routeUndo.shift();updateUndoButton()}}
function undoRouteEdit(){const u=S.routeUndo.pop();if(!u)return;S.selected=u.index;S.route=u.route;S.routes[u.index]=u.route;clearLines();line('chosen',u.route.geometry,colors[u.index%colors.length],8);nodes();cards();updateUndoButton()}
function updateUndoButton(){const b=$('#route-undo');if(b){b.hidden=!S.routeUndo.length||S.page!=='explore';b.onclick=undoRouteEdit}}
function savedRouteBadges(item){const route=item.route||{},badges=[];if(item.mode==='loop'||isClosedLoop(route.geometry?.coordinates||[]))badges.push('Loop');if(route.imported||item.importedAt)badges.push('Imported GPX');if(route.waypointEfficient)badges.push('Waypoint return');if(route.narrowLoop)badges.push('Corridor loop');if(route.adventureProfile)badges.push(adventureProfileTitle(route.adventureProfile));return badges.slice(0,4)}
function savedRouteDate(item){const stamp=item.updatedAt||item.importedAt||item.savedAt;return stamp?new Date(stamp).toLocaleDateString([],{day:'numeric',month:'short',year:'numeric'}):'Saved route'}
function savedRouteMiniChart(values,color){if(!Array.isArray(values)||values.length<2)return'<div class="saved-mini-empty">Profile unavailable</div>';const lo=Math.min(...values),hi=Math.max(...values),points=values.map((v,i)=>`${(i/(values.length-1)*100).toFixed(1)},${(34-(v-lo)/(hi-lo||1)*28).toFixed(1)}`).join(' ');return`<svg class="saved-mini-chart" viewBox="0 0 100 38" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.2" vector-effect="non-scaling-stroke"/></svg>`}
function loadSavedRoute(x,edit=true){S.route=structuredClone(x.route);S.routes=[S.route];S.selected=0;S.waypoints=structuredClone(x.waypoints||[]);S.names=structuredClone(x.names||[]);S.mode=x.mode||'point';S.editingSavedId=x.id||null;S.route.savedName=x.name||'Saved route';clearLines();line('chosen',S.route.geometry,colors[0],8);open('explore');cards();if(edit)nodes();updateQuickNav();toast(edit?'Saved route opened in edit mode':'Saved route opened')}
function exportSelectedRouteGpx(){if(!S.route)return toast('Select a route first');const name=S.names.length?`${S.names[0]} to ${S.names.at(-1)}`:'Ridewise route',xml=`<?xml version="1.0"?><gpx version="1.1" creator="Ridewise" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>${escapeHtml(name)}</name><trkseg>${S.route.geometry.coordinates.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}"></trkpt>`).join('')}</trkseg></trk></gpx>`,a=document.createElement('a');a.href=URL.createObjectURL(new Blob([xml],{type:'application/gpx+xml'}));a.download='ridewise-route.gpx';a.click()}
async function getCloud(){if(S.cloud)return S.cloud;const m=await import('https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js'),app=(await import('https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js')).getApp();S.cloud={...m,firestore:m.getFirestore(app)};return S.cloud}
async function startLiveJourney(){if(!S.route)return toast('Select a route first');if(!S.user)return toast('Sign in first');const db=await getCloud(),ref=await db.addDoc(db.collection(db.firestore,'journeys_v4'),{ownerId:S.user.uid,active:true,paused:false,routeJson:JSON.stringify(S.route.geometry),routeName:S.route.savedName||S.route.name||'Live Ridewise route',location:S.pos?{lng:S.pos[0],lat:S.pos[1],accuracy:null,heading:S.visualHeading??S.smoothedHeading??null}:null,updatedAt:db.serverTimestamp()});S.liveJourney={ref,id:ref.id,paused:false};toast('Live progression started')}
async function toggleLiveSharingPause(){if(!S.liveJourney)return;S.liveJourney.paused=!S.liveJourney.paused;const db=await getCloud();await db.setDoc(S.liveJourney.ref,{paused:S.liveJourney.paused,updatedAt:new Date()},{merge:true});toast(S.liveJourney.paused?'Live sharing paused':'Live sharing resumed')}
async function updateLiveJourney(pos,accuracy=null,heading=null){if(!S.liveJourney||S.liveJourney.paused)return;const now=Date.now();if(S.liveJourney.lastUpdate&&now-S.liveJourney.lastUpdate<1500)return;S.liveJourney.lastUpdate=now;try{const db=await getCloud();await db.setDoc(S.liveJourney.ref,{location:{lng:pos[0],lat:pos[1],accuracy:Number.isFinite(accuracy)?accuracy:null,heading:Number.isFinite(heading)?heading:null},active:true,paused:false,updatedAt:new Date()},{merge:true})}catch(error){console.warn('Live location update failed',error)}}
function sharedJourneyMarker(kind){const element=document.createElement('div');element.className=`live-map-marker ${kind}`;element.innerHTML=kind==='rider'?'<span class="live-marker-ring"></span><span class="live-marker-dot"></span><b>Rider</b>':'<span class="viewer-marker-halo"></span><span class="viewer-marker-dot"></span><b>You</b>';return element}
function ensureSharedJourneyStatus(){let box=$('#shared-journey-status');if(!box){box=document.createElement('section');box.id='shared-journey-status';box.className='shared-journey-status';box.innerHTML='<b>Live journey</b><span id="shared-journey-state">Connecting…</span><small id="shared-journey-updated"></small>';$('#map-wrap')?.appendChild(box)}return box}
function drawSharedJourneyRoute(geometry){if(!geometry?.coordinates?.length)return;for(const id of['shared-journey-route']){if(map.getLayer(id))map.removeLayer(id);if(map.getSource(id))map.removeSource(id)}map.addSource('shared-journey-route',{type:'geojson',data:{type:'Feature',geometry,properties:{}}});map.addLayer({id:'shared-journey-route',type:'line',source:'shared-journey-route',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#8b5bd6','line-width':7,'line-opacity':.9}})}
function fitSharedJourneyView(routeGeometry,rider,viewer){if(S.sharedJourneyFitted)return;const features=[];if(routeGeometry?.coordinates?.length)features.push({type:'Feature',geometry:routeGeometry,properties:{}});if(rider)features.push(turf.point(rider));if(viewer)features.push(turf.point(viewer));if(!features.length)return;const bbox=turf.bbox({type:'FeatureCollection',features});map.fitBounds([[bbox[0],bbox[1]],[bbox[2],bbox[3]]],{padding:mobile()?{top:100,left:35,right:35,bottom:170}:{top:70,left:120,right:70,bottom:70},maxZoom:16.5,duration:900});S.sharedJourneyFitted=true}
function beginViewerLocation(){if(S.viewerWatch!==null)return;S.viewerWatch=navigator.geolocation.watchPosition(position=>{const point=[position.coords.longitude,position.coords.latitude];if(!S.viewerMarker)S.viewerMarker=new mapboxgl.Marker({element:sharedJourneyMarker('viewer')}).setLngLat(point).addTo(map);else S.viewerMarker.setLngLat(point);const route=S.sharedJourneyState?.routeJson?JSON.parse(S.sharedJourneyState.routeJson):null,rider=S.sharedJourneyState?.location?[S.sharedJourneyState.location.lng,S.sharedJourneyState.location.lat]:null;fitSharedJourneyView(route,rider,point)},error=>console.warn('Viewer location unavailable',error),{enableHighAccuracy:true,maximumAge:5000,timeout:10000})}
function renderSharedJourneySnapshot(data){S.sharedJourneyState=data;let geometry=null;try{geometry=typeof data.routeJson==='string'?JSON.parse(data.routeJson):data.routeJson}catch(error){console.warn('Invalid live route geometry',error)}if(geometry?.coordinates?.length)drawSharedJourneyRoute(geometry);const rider=data.location&&Number.isFinite(data.location.lng)&&Number.isFinite(data.location.lat)?[data.location.lng,data.location.lat]:null;if(rider){if(!S.sharedRiderMarker)S.sharedRiderMarker=new mapboxgl.Marker({element:sharedJourneyMarker('rider')}).setLngLat(rider).addTo(map);else S.sharedRiderMarker.setLngLat(rider);const heading=data.location.heading;if(Number.isFinite(heading))S.sharedRiderMarker.getElement().style.setProperty('--rider-heading',`${heading}deg`)}const status=ensureSharedJourneyStatus(),state=$('#shared-journey-state'),updated=$('#shared-journey-updated');state.textContent=!data.active?'Journey ended':data.paused?'Live sharing paused':rider?'Rider position is live':'Waiting for rider GPS';const date=data.updatedAt?.toDate?.()||new Date(data.updatedAt||Date.now());updated.textContent=`Last update ${date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;const viewer=S.viewerMarker?.getLngLat?.();fitSharedJourneyView(geometry,rider,viewer?[viewer.lng,viewer.lat]:null)}
async function watchSharedJourney(id){if(!id||S.sharedJourneyId===id)return;const user=await authReady;if(!user){open('profile');toast('Sign in to view this live journey');return}S.sharedJourneyId=id;S.sharedJourneyFitted=false;open('explore');ensureSharedJourneyStatus();beginViewerLocation();try{const db=await getCloud();S.liveUnsub?.();S.liveUnsub=db.onSnapshot(db.doc(db.firestore,'journeys_v4',id),snapshot=>{if(!snapshot.exists()){ensureSharedJourneyStatus();$('#shared-journey-state').textContent='Journey not found';return}renderSharedJourneySnapshot(snapshot.data())},error=>{console.error('Live journey subscription failed',error);$('#shared-journey-state').textContent=error.code==='permission-denied'?'Sign in required to view':'Live journey unavailable'})}catch(error){console.error('Could not watch live journey',error);toast('Could not open live journey')}}
async function loadJourneyFromUrl(){const id=new URLSearchParams(location.search).get('journey');if(id)await watchSharedJourney(id)}

function navigationRouteStyle(pos){if(!S.route||!pos)return;const l=turf.lineString(S.route.geometry.coordinates),total=turf.length(l),snap=turf.nearestPointOnLine(l,turf.point(pos)),at=snap.properties.location||0;['nav-travelled','nav-upcoming','nav-future'].forEach(id=>{if(map.getLayer(id))map.removeLayer(id);if(map.getSource(id))map.removeSource(id)});const add=(id,a,b,color,opacity,width)=>{if(b-a<.005)return;map.addSource(id,{type:'geojson',data:turf.lineSliceAlong(l,a,b)});map.addLayer({id,type:'line',source:id,paint:{'line-color':color,'line-opacity':opacity,'line-width':width}})};add('nav-travelled',0,at,'#687789',.6,6);add('nav-upcoming',at,Math.min(total,at+1.25),'#00a8ff',1,9);add('nav-future',Math.min(total,at+1.25),total,'#176bdb',.24,6)}
function showNavigationAlternatives(){if(!S.navState)return;S.routes.forEach((route,i)=>{if(i===S.selected||!route?.geometry||hasMotorway(route))return;const id=`nav-alt-${i}`;if(map.getLayer(id))return;map.addSource(id,{type:'geojson',data:{type:'Feature',geometry:route.geometry}});map.addLayer({id,type:'line',source:id,paint:{'line-color':'#687789','line-width':5,'line-opacity':.48,'line-dasharray':[2,2]}});addRouteDirectionArrows(id,'#687789',5);map.on('mouseenter',id,()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave',id,()=>map.getCanvas().style.cursor='');map.on('click',id,e=>{const previous=S.route,timeDifference=Math.round(((route.duration||0)-(previous?.duration||0))/60),distanceDifference=((route.distance||0)-(previous?.distance||0))/1000;S.selected=i;S.route=route;S.navState.steps=route.legs?.flatMap(l=>l.steps||[])||[];S.navState.index=0;clearNavigationAlternativeLayers();line('chosen',route.geometry,colors[i%colors.length],8);showNavigationAlternatives();updateNavigationGuidance(S.pos||route.geometry.coordinates[0]);const reason=timeDifference<0?`${Math.abs(timeDifference)} min faster`:distanceDifference<-.2?`${Math.abs(distanceDifference).toFixed(1)} km shorter`:timeDifference>0?`${timeDifference} min longer`:'similar time';new mapboxgl.Popup({closeButton:true}).setLngLat(e.lngLat).setHTML(`<b>Alternative selected</b><br>${reason}`).addTo(map);toast(`Alternative route selected · ${reason}`)})})}
function clearNavigationAlternativeLayers(){[...S.layers.filter(id=>id.startsWith('nav-alt-'))].forEach(id=>{if(map.getLayer(`${id}-direction`))map.removeLayer(`${id}-direction`);if(map.getLayer(id))map.removeLayer(id);if(map.getSource(id))map.removeSource(id)});S.layers=S.layers.filter(id=>!id.startsWith('nav-alt-'))}

function toggleAudioNavigation(){S.audioNavigation=!S.audioNavigation;localStorage.setItem('audioNavigation',S.audioNavigation?'on':'off');$('#audio-nav').textContent=S.audioNavigation?'🔊':'🔇';if(S.audioNavigation)unlockAudioNavigation();else speechSynthesis.cancel()}
function unlockAudioNavigation(){S.audioUnlocked=true;if('speechSynthesis'in window){speechSynthesis.getVoices();const u=new SpeechSynthesisUtterance('Voice guidance on');speechSynthesis.speak(u)}}
function updateTravelHeading(pos,time=Date.now()){S.headingSamples.push({pos,time});S.headingSamples=S.headingSamples.filter(x=>time-x.time<=4000);if(S.headingSamples.length<2)return S.smoothedHeading;const f=S.headingSamples[0];if(turf.distance(f.pos,pos,{units:'meters'})<3){S.headingUnstable=true;return S.smoothedHeading}S.smoothedHeading=(turf.bearing(f.pos,pos)+360)%360;S.headingUnstable=false;return S.smoothedHeading}
function checkWrongDirection(pos,speed,heading){if(!S.route||!Number.isFinite(heading)||speed<1.5)return;const snap=turf.nearestPointOnLine(turf.lineString(S.route.geometry.coordinates),turf.point(pos)),i=Math.min((snap.properties.index||0)+2,S.route.geometry.coordinates.length-1),expected=turf.bearing(pos,S.route.geometry.coordinates[i]),diff=Math.abs(((heading-expected+540)%360)-180);if(diff>105){if(!S.wrongWaySince)S.wrongWaySince=Date.now();if(Date.now()-S.wrongWaySince>7000)recalculateFrom(pos)}else S.wrongWaySince=null}
function toggleRecordingPause(){if(!S.record)return;S.record.manualPaused=!S.record.manualPaused;syncPauseControls()}
function toggleNavigationPause(){if(!S.navState)return;S.navState.paused=!S.navState.paused;syncPauseControls()}
function syncPauseControls(){const pr=$('#pause-recording'),pn=$('#pause-navigation'),er=$('#end-recording'),en=$('#end-navigation');if(pr)pr.textContent=S.record?.manualPaused?'Resume recording':'Pause recording';if(pn)pn.textContent=S.navState?.paused?'Resume navigation':'Pause navigation';if(er)er.hidden=!S.record?.manualPaused;if(en)en.hidden=!S.navState?.paused}
function select(i){stop3DPreview();S.selected=i;S.route=S.routes[i];clearLines();line('chosen',S.route.geometry,colors[i%colors.length],8);nodes();cards();updateQuickNav()}function drawCharts(){document.querySelectorAll('[data-e]').forEach(c=>{const r=S.routes[+c.dataset.e];plot(c,Array.isArray(r?.elev)?r.elev:[],'#139b66','m')});document.querySelectorAll('[data-w]').forEach(c=>{const r=S.routes[+c.dataset.w];plotSignedWind(c,Array.isArray(r?.wind)?r.wind:[],'km/h')})}function plot(c,a=[],col,unit=''){if(!c||!Array.isArray(a)||!a.length){drawChartPlaceholder(c,'Loading data…');return;}const d=devicePixelRatio||1,rect=c.getBoundingClientRect(),w=Math.max(280,Math.round(rect.width)),h=Math.max(120,Math.round(rect.height));c.width=w*d;c.height=h*d;const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);const lo=Math.min(...a),hi=Math.max(...a),left=44,right=8,top=10,bottom=24;x.strokeStyle='#dbe2ea';x.lineWidth=1;x.beginPath();x.moveTo(left,top);x.lineTo(left,h-bottom);x.lineTo(w-right,h-bottom);x.stroke();x.fillStyle='#657186';x.font='10px system-ui';x.fillText(`${Math.round(hi)}${unit?' '+unit:''}`,3,top+4);x.fillText(`${Math.round(lo)}${unit?' '+unit:''}`,3,h-bottom+4);x.fillText('start',left,h-6);x.fillText('finish',w-38,h-6);x.strokeStyle=col;x.lineWidth=2.5;x.beginPath();a.forEach((v,i)=>{const px=left+i*(w-left-right)/Math.max(1,a.length-1),py=h-bottom-(v-lo)*(h-top-bottom)/(hi-lo||1);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}
function plotSignedWind(c,a=[],unit='km/h'){if(!c||!Array.isArray(a)||!a.length){drawChartPlaceholder(c,'Loading wind…');return;}const d=devicePixelRatio||1,rect=c.getBoundingClientRect(),w=Math.max(280,Math.round(rect.width)),h=Math.max(120,Math.round(rect.height));c.width=w*d;c.height=h*d;const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);const max=Math.max(5,...a.map(v=>Math.abs(v))),left=45,right=8,mid=h/2;x.clearRect(0,0,w,h);x.strokeStyle='#9aa7b5';x.beginPath();x.moveTo(left,mid);x.lineTo(w-right,mid);x.stroke();x.font='10px system-ui';x.fillStyle='#657186';x.fillText(`+${Math.round(max)} ${unit}`,2,12);x.fillText('0',25,mid+3);x.fillText(`−${Math.round(max)} ${unit}`,2,h-5);a.forEach((v,i)=>{const x0=left+i*(w-left-right)/a.length,x1=left+(i+1)*(w-left-right)/a.length,y=mid-v/max*(h/2-14);x.fillStyle=v>=0?'#139b66':'#d94d4d';x.fillRect(x0,Math.min(mid,y),Math.max(2,x1-x0-1),Math.abs(mid-y))});x.fillStyle='#139b66';x.fillText('tailwind',left+3,12);x.fillStyle='#d94d4d';x.fillText('headwind',left+3,h-5)}
function drawChartPlaceholder(c,text){if(!c)return;const d=devicePixelRatio||1,rect=c.getBoundingClientRect(),w=Math.max(280,Math.round(rect.width||280)),h=Math.max(120,Math.round(rect.height||120));c.width=w*d;c.height=h*d;const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);x.fillStyle='#657186';x.font='11px system-ui';x.textAlign='center';x.fillText(text,w/2,h/2);x.textAlign='start'}
function nodes(){S.nodes.forEach(m=>m.remove());S.nodes=[];const steps=S.route?.legs?.flatMap(l=>l.steps)||[];steps.slice(1,-1).forEach((step,stepIndex)=>{const el=document.createElement('div');el.className='turn';el.title='Drag to reshape this route';const marker=new mapboxgl.Marker({element:el,draggable:true}).setLngLat(step.maneuver.location).addTo(map);marker.on('dragend',async()=>{const dragged=marker.getLngLat().toArray();await reshapeSelectedRoute(dragged,step.maneuver.location);});S.nodes.push(marker)})}
function isClosedLoop(coords,toleranceKm=.18){return Array.isArray(coords)&&coords.length>2&&Array.isArray(coords[0])&&Array.isArray(coords.at(-1))&&turf.distance(coords[0],coords.at(-1),{units:'kilometers'})<=toleranceKm}
function dedupeViaPoints(points,toleranceKm=.015){const out=[];for(const point of points||[]){if(!Array.isArray(point)||point.length<2||!point.every(Number.isFinite))continue;if(!out.length||turf.distance(out.at(-1),point,{units:'kilometers'})>toleranceKm)out.push([...point])}return out}
function buildLoopViaPoints(coords,dragged,original){const lineString=turf.lineString(coords),length=turf.length(lineString),snap=turf.nearestPointOnLine(lineString,turf.point(original)),fraction=Math.max(0,Math.min(1,(snap.properties.location||0)/(length||1))),anchors=[];for(let i=0;i<8;i++){const f=i/8;if(Math.abs(f-fraction)>.075)anchors.push({f,coord:turf.along(lineString,length*f).geometry.coordinates})}anchors.push({f:fraction,coord:[...dragged]});anchors.sort((a,b)=>a.f-b.f);const start=[...coords[0]],ordered=[start,...anchors.filter(anchor=>anchor.f>.02&&anchor.f<.98).map(anchor=>anchor.coord),start];return dedupeViaPoints(ordered)}
function routeRequiredWaypoints(route){if(Array.isArray(route?.requiredNavigationWaypoints)&&route.requiredNavigationWaypoints.length)return route.requiredNavigationWaypoints.filter(point=>Array.isArray(point)).map(point=>[...point]);const request=route?._requestPoints;if(Array.isArray(request)&&request.length>2)return request.slice(1).filter(point=>Array.isArray(point)).map(point=>[...point]);if(S.mode==='loop'){const start=route?.geometry?.coordinates?.[0],required=S.adventureWaypoints.map(item=>item?.coord).filter(point=>Array.isArray(point));return[...required,...(start?[start]:[])].map(point=>[...point])}return(S.waypoints||[]).slice(1).filter(point=>Array.isArray(point)).map(point=>[...point])}
