async function reshapeSelectedRoute(dragged,original){if(!S.route||S.selected===null)return;const oldRoute=S.route,isLoop=isClosedLoop(oldRoute.geometry.coordinates),required=routeRequiredWaypoints(oldRoute);toast(required.length?'Reshaping while preserving every waypoint…':isLoop?'Reshaping loop while preserving its circuit…':'Reshaping selected route…');pushRouteUndo();try{const via=buildWaypointPreservingEditPoints(oldRoute,dragged,original),candidates=await directions(via,false),next=candidates[0];if(!next)throw new Error('No reshaped route returned');if(isLoop&&!validLoop(next.geometry.coordinates,oldRoute.geometry.coordinates))throw new Error('The reshaped result collapsed the loop');if(!routeContainsRequiredWaypoints(next,required))throw new Error('The reshaped route omitted a required waypoint');next._requestPoints=structuredClone(via);next.requiredNavigationWaypoints=structuredClone(required);next.requiredWaypointNames=structuredClone(oldRoute.requiredWaypointNames||[]);next.waypointEfficient=oldRoute.waypointEfficient;next.qualityLabel=oldRoute.qualityLabel;next.rangeStatus=oldRoute.rangeStatus;next.savedName=oldRoute.savedName;await enrich(next);next.poi=oldRoute.poi;next.name=oldRoute.name;next.cycleScore=cycleScore(next);S.routes[S.selected]=next;S.route=next;if(S.editingSavedId)await saveEditedSavedRoute();clearLines();line('chosen',next.geometry,colors[S.selected%colors.length],8);nodes();cards();updateQuickNav();toast(required.length?'Route reshaped · all waypoints preserved':isLoop?'Loop reshaped and preserved':'Route reshaped')}catch(error){console.warn('Route reshaping rejected:',error);S.route=oldRoute;S.routes[S.selected]=oldRoute;clearLines();line('chosen',oldRoute.geometry,colors[S.selected%colors.length],8);nodes();cards();toast(required.length?'Edit rejected because a required waypoint would be lost':'That edit would collapse the loop, so the previous route was restored')}}

