function stars(){S.poiMarkers.forEach(m=>m.remove());S.poiMarkers=[];S.routes.forEach((r,i)=>{if(!r.poi)return;const e=document.createElement('button');e.className='poi-star';e.textContent='★';S.poiMarkers.push(new mapboxgl.Marker({element:e}).setLngLat(r.poi.center).setPopup(new mapboxgl.Popup().setHTML(`<b>★ ${r.poi.name}</b><br>Considered for option ${i+1}`)).addTo(map))})}
function markers(){S.markers.forEach(m=>m.remove());S.markers=[];S.waypoints.filter(Boolean).forEach(p=>S.markers.push(new mapboxgl.Marker().setLngLat(p).addTo(map)))}
function updateQuickNav(){const box=$('#quick-nav'),quickStart=$('#quick-start'),live=$('#ride-live');if(!box||!quickStart||!live)return;const routeReady=!!S.route&&S.selected!==null,active=!!S.record||!!S.navState;box.hidden=!routeReady&&!active;quickStart.hidden=active;live.hidden=!active;box.classList.toggle('recording-active',active);if(routeReady&&!active)quickStart.onclick=startNavigation;if(active){box.style.display='block';box.style.visibility='visible';box.style.opacity='1';live.style.display='block';quickStart.style.display='none'}else{box.style.display=box.hidden?'none':'';live.style.display='none';quickStart.style.display=''}}
