function updateOfflineNavigationStatus(){let badge=$('#offline-nav-status');if(!badge){badge=document.createElement('div');badge.id='offline-nav-status';badge.className='offline-nav-status';$('#map-wrap')?.appendChild(badge)}const active=!!S.navState&&!navigator.onLine;badge.hidden=!active;if(active)badge.textContent='Offline navigation · GPS guidance active · rerouting unavailable'}
const ACTIVE_SESSION_KEY='ridewise-active-session-v1';let sessionSaveTimer=0;function serialisableSession(){if(!S.record&&!S.navState)return null;return{version:1,ownerId:S.user?.uid||null,savedAt:Date.now(),route:S.route?structuredClone(S.route):null,routes:structuredClone(S.routes||[]),selected:S.selected,waypoints:structuredClone(S.waypoints||[]),names:structuredClone(S.names||[]),mode:S.mode,record:S.record?structuredClone(S.record):null,navState:S.navState?{...structuredClone(S.navState),recalculating:false}:null,pos:S.pos||null,visualHeading:S.visualHeading??S.smoothedHeading??null}}function persistActiveSession(force=false){clearTimeout(sessionSaveTimer);const commit=()=>{const data=serialisableSession();if(data)localStorage.setItem(ACTIVE_SESSION_KEY,JSON.stringify(data));else localStorage.removeItem(ACTIVE_SESSION_KEY)};if(force)commit();else sessionSaveTimer=setTimeout(commit,800)}function clearActiveSession(){clearTimeout(sessionSaveTimer);localStorage.removeItem(ACTIVE_SESSION_KEY)}function getRecoverableSession(){try{const data=JSON.parse(localStorage.getItem(ACTIVE_SESSION_KEY));return data&&S.user&&data.ownerId===S.user.uid&&Date.now()-data.savedAt<7*86400000?data:null}catch{return null}}function restoreActiveSession(data){if(!data)return;S.route=data.route;S.routes=data.routes?.length?data.routes:(data.route?[data.route]:[]);S.selected=Number.isInteger(data.selected)?data.selected:(S.route?0:null);S.waypoints=data.waypoints||[];S.names=data.names||[];S.mode=data.mode||'point';S.record=data.record||null;S.navState=data.navState||null;if(S.navState&&!Array.isArray(S.navState.requiredWaypoints)){S.navState.requiredWaypoints=navigationWaypointSequence();S.navState.requiredWaypointIndex=0;S.navState.visitedWaypoints=[]}if(S.navState)S.navState.waypointArrivalHits=0;S.pos=data.pos||S.pos;S.visualHeading=data.visualHeading??null;if(S.record){S.record.lastTick=Date.now();S.record.paused=false;S.record.stationarySince=null}if(S.route){clearLines();line('chosen',S.route.geometry,colors[(S.selected||0)%colors.length],8)}watch();open('explore');if(S.navState){$('#nav-guidance').hidden=false;showNavigationAlternatives();updateNavigationGuidance(S.pos||S.route?.geometry?.coordinates?.[0])}updateQuickNav();persistActiveSession(true);toast(S.navState?'Navigation restored':'Recording restored')}function promptSessionRecovery(){const data=getRecoverableSession();if(!data)return;const box=createChoiceModal('Unfinished ride found',`<p>${data.navState?'Navigation and recording':'Recording'} from ${new Date(data.savedAt).toLocaleString()}.</p><button id="resumeSession">${data.navState?'Resume navigation':'Resume recording'}</button><button id="savePartialSession">Save partial activity</button><button id="discardSession">Discard</button>`);$('#resumeSession').onclick=()=>{box.remove();restoreActiveSession(data)};$('#savePartialSession').onclick=()=>{box.remove();restoreActiveSession(data);finishRecord(true)};$('#discardSession').onclick=()=>{clearActiveSession();box.remove();toast('Unfinished ride discarded')}}
function navigationWaypointSequence(){const attached=S.route?.requiredNavigationWaypoints;if(Array.isArray(attached)&&attached.length)return attached.filter(point=>Array.isArray(point)).map(point=>[...point]);const request=S.route?._requestPoints;if(Array.isArray(request)&&request.length>1)return request.slice(1).filter(point=>Array.isArray(point)).map(point=>[...point]);const start=S.route?.geometry?.coordinates?.[0];if(S.mode==='loop'){const required=S.adventureWaypoints.map(item=>item?.coord).filter(point=>Array.isArray(point));return [...required,...(start?[start]:[])].map(point=>[...point])}return(S.waypoints||[]).slice(1).filter(point=>Array.isArray(point)).map(point=>[...point])}
function dedupeNavigationPoints(points){const out=[];for(const point of points)if(!out.length||turf.distance(out.at(-1),point)>.005)out.push([...point]);return out}
function initialiseNavigationWaypoints(){const requiredWaypoints=navigationWaypointSequence();S.route.requiredNavigationWaypoints=structuredClone(requiredWaypoints);S.navState.requiredWaypoints=structuredClone(requiredWaypoints);S.navState.requiredWaypointIndex=0;S.navState.visitedWaypoints=[];S.navState.waypointArrivalHits=0;S.navState.originalRequestPoints=structuredClone(S.route?._requestPoints||S.waypoints||[])}
