function laneText(step){const lanes=step?.intersections?.flatMap(i=>i.lanes||[]).filter(l=>l.valid||l.active);if(lanes?.length)return`Use ${lanes.map(l=>(l.indications||[]).join('/')).filter(Boolean).join(', ')} lane`;const road=step?.name||step?.ref;return road?`Continue toward ${road}`:''}
function turnArrow(m={}){const mod=m.modifier||'',type=m.type||'';if(type==='roundabout'||type==='rotary')return'↻';if(mod.includes('left'))return mod.includes('slight')?'↖':'←';if(mod.includes('right'))return mod.includes('slight')?'↗':'→';if(mod.includes('uturn'))return'↩';return'↑'}function formatDistance(m){return m>=1000?`${(m/1000).toFixed(m>=10000?0:1)} km`:`${Math.max(10,Math.round(m/10)*10)} m`}
function stopRecording(){finishRecord(false)}function endNavigation(){finishRecord(true)}async function finishRecord(endNav=true){const r=S.record;if(!r)return;if(S.watch!==null)navigator.geolocation.clearWatch(S.watch);S.watch=null;const startPos=r.samples?.[0]?.pos,endPos=r.samples?.at(-1)?.pos;let defaultName=S.names.length?`${S.names[0]} to ${S.names.at(-1)}`:'Cycling activity';if((!S.names.length||defaultName==='Cycling activity')&&startPos&&endPos){try{const names=await Promise.all([startPos,endPos].map(p=>fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${p.join(',')}.json?limit=1&access_token=${MAPBOX_TOKEN}`).then(x=>x.json()).then(d=>d.features?.[0]?.text||'Start')));defaultName=`${names[0]} to ${names[1]}`}catch{}}const metrics=activityMetrics(r);S.pendingActivity={...r,...metrics,id:crypto.randomUUID(),name:defaultName,ended:Date.now(),elapsed:r.movingMs,avgSpeed:r.movingMs>0?r.distance/(r.movingMs/36e5):0,photos:[]};S.record=null;clearActiveSession();clearLines();S.routes=[];S.route=null;S.selected=null;await releaseScreenWakeLock();if(endNav){S.navState=null;$('#nav-guidance').hidden=true;window.speechSynthesis?.cancel()}updateQuickNav();S.page='record';document.body.classList.add('panel-open');render();toast('Ride complete. Name it and add a photo.')}
async function shareSavedActivity(a){const text=`${a.name}: ${a.distance.toFixed(1)} km, ${Math.round(a.gain||0)} m climbing, ${a.avgSpeed.toFixed(1)} km/h, effort ${Math.round(a.effortScore||0)}.`;try{const blob=await activityPngBlob(a),file=new File([blob],`${safeName(a.name)}.png`,{type:'image/png'}),data={title:a.name,text,files:[file]};if(navigator.canShare?.({files:[file]}))await navigator.share(data);else if(navigator.share)await navigator.share({title:a.name,text});else{await navigator.clipboard.writeText(text);toast('Activity summary copied')}}catch(e){if(e.name!=='AbortError'){console.error(e);toast('Could not share activity')}}}
async function exportActivityPng(a){const blob=await activityPngBlob(a),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${safeName(a.name)}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function activityPngBlob(a){const c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,1080,1350);g.addColorStop(0,'#15324d');g.addColorStop(1,'#176bdb');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.fillStyle='#fff';x.font='700 48px system-ui';x.fillText('RIDEWISE',60,78);x.font='800 58px system-ui';wrapCanvasText(x,a.name||'Cycling activity',60,160,950,68);x.font='800 82px system-ui';x.fillText(`${a.distance.toFixed(1)} KM`,60,300);x.font='32px system-ui';x.fillText(`${a.avgSpeed.toFixed(1)} km/h avg   ·   ${Math.round(a.gain||0)} m climbing`,60,350);x.fillText(`${Math.round(a.avgPower||0)} W estimated   ·   effort ${Math.round(a.effortScore||0)}`,60,395);try{x.drawImage(map.getCanvas(),60,445,960,570)}catch{}const photo=(a.photos||[])[0];if(photo){try{const img=await loadImage(photo);x.drawImage(img,60,1040,300,230)}catch{}}x.fillStyle='#fff';x.font='26px system-ui';x.fillText('Ride planned and recorded with Ridewise',60,1320);return new Promise(resolve=>c.toBlob(resolve,'image/png',.92))}
function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src})}function safeName(n='activity'){return n.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'activity'}function wrapCanvasText(ctx,text,x,y,maxWidth,lineHeight){const words=text.split(' ');let line='';for(const word of words){const test=line+word+' ';if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,y);line=word+' ';y+=lineHeight}else line=test}ctx.fillText(line,x,y)}
function routes(){if(!S.user){panel.innerHTML=head('Routes','Account-specific saved routes')+'<div class="card account-required"><h2>Sign in required</h2><p>Saved routes are private to your account and synchronise across signed-in devices.</p><button class="btn primary" id="routeSignIn">Sign in</button></div>';$('#routeSignIn').onclick=()=>open('profile');return}const saved=S.accountRoutes;panel.innerHTML=head('Routes','Saved, editable and ready to ride')+`<div class="saved-routes-toolbar"><label class="btn primary file-label">Import GPX<input id="importGpx" type="file" accept=".gpx,application/gpx+xml,application/xml,text/xml" hidden></label><span>${saved.length} saved route${saved.length===1?'':'s'}</span></div><div class="saved-route-grid">${saved.length?saved.map((item,i)=>{const route=item.route||{},badges=savedRouteBadges(item),color=colors[i%colors.length],cycle=Number.isFinite(route.cycleScore)?route.cycleScore:0;return`<article class="saved-route-card" style="--saved-color:${color}"><div class="saved-route-accent"></div><div class="saved-route-head"><div><small>${escapeHtml(savedRouteDate(item))}</small><h2>${escapeHtml(item.name||'Saved route')}</h2></div><button class="saved-route-menu" data-rename="${i}" title="Rename route">✎</button></div><div class="saved-route-badges">${badges.length?badges.map(b=>`<span>${escapeHtml(b)}</span>`).join(''):'<span>Saved cycling route</span>'}</div><div class="saved-route-stats"><div><b>${fmt((route.distance||0)/1000)}</b><small>km</small></div><div><b>${Math.round((route.duration||0)/60)}</b><small>min</small></div><div><b>${Math.round(route.ascent||0)}</b><small>climb m</small></div><div><b>${cycle}%</b><small>cycle cues</small></div></div><div class="saved-route-profiles"><div><small>Elevation</small>${savedRouteMiniChart(route.elev,'#16a36d')}</div><div><small>Wind</small>${savedRouteMiniChart(route.wind,'#176bdb')}</div></div><div class="saved-route-summary">${route.qualityLabel?escapeHtml(route.qualityLabel):item.mode==='loop'?'Saved Adventure loop':'Saved route'}${route.rangeStatus?` · ${escapeHtml(route.rangeStatus)}`:''}</div><div class="saved-route-actions"><button class="btn primary" data-open="${i}">Open & edit</button><button data-share-saved="${i}">↗ Share</button><button data-preview-saved="${i}">▶ Preview</button><button data-gpx="${i}">GPX</button><button data-delete="${i}" class="danger-soft">Delete</button></div></article>`}).join(''):'<div class="empty saved-route-empty"><b>No saved routes yet</b><span>Save an Adventure or point-to-point route to edit it later.</span></div>'}</div>`;$('#importGpx').onchange=e=>importGpxFile(e.target.files[0]);panel.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>loadSavedRoute(saved[+b.dataset.open],true));panel.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>renameSavedRoute(saved,+b.dataset.rename));panel.querySelectorAll('[data-share-saved]').forEach(b=>b.onclick=()=>shareSavedRouteByIndex(+b.dataset.shareSaved));panel.querySelectorAll('[data-preview-saved]').forEach(b=>b.onclick=()=>{loadSavedRoute(saved[+b.dataset.previewSaved],false);previewRoute3D()});panel.querySelectorAll('[data-gpx]').forEach(b=>b.onclick=()=>{loadSavedRoute(saved[+b.dataset.gpx],false);exportSelectedRouteGpx()});panel.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this saved route?'))return;deleteAccountItem('routes',saved[+b.dataset.delete].id).then(routes)})}

async function importGpxFile(file){if(!file)return;if(!requireAccount('import and save routes'))return;try{const text=await file.text(),xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw new Error('Invalid GPX XML');let points=[...xml.querySelectorAll('trkpt')];if(points.length<2)points=[...xml.querySelectorAll('rtept')];const coords=points.map(p=>[+p.getAttribute('lon'),+p.getAttribute('lat')]).filter(p=>p.every(Number.isFinite));if(coords.length<2)throw new Error('No track or route points');const geometry={type:'LineString',coordinates:coords},distance=turf.length(turf.lineString(coords),{units:'kilometers'})*1000,elev=points.map(p=>+p.querySelector('ele')?.textContent).filter(Number.isFinite),name=xml.querySelector('trk>name,rte>name,metadata>name')?.textContent?.trim()||file.name.replace(/\.gpx$/i,'');const route={geometry,distance,duration:0,elev,ascent:gain(elev),legs:[],cycleScore:0,imported:true};const item=await putAccountItem('routes',{id:crypto.randomUUID(),name,route,names:[name],waypoints:[coords[0],coords.at(-1)],mode:'point',importedAt:Date.now()});loadSavedRoute(item);toast('GPX imported to your account');routes()}catch(error){console.error(error);toast(`GPX import failed: ${error.message}`)}}

function absoluteAppUrl(params={}){const url=new URL(location.href);url.search='';url.hash='';for(const[key,value]of Object.entries(params))if(value!==null&&value!==undefined&&value!=='')url.searchParams.set(key,String(value));return url.toString()}
async function copyShareUrl(url){try{await navigator.clipboard.writeText(url);toast('Share URL copied')}catch{prompt('Copy share URL',url)}}
function showUrlShareWindow(title,url,text=''){const box=createChoiceModal(title,`<p>${escapeHtml(text)}</p><label class="share-link-label">Share URL</label><div class="share-link-row"><input id="shareUrlValue" value="${escapeHtml(url)}" readonly><button id="copyShareUrl">Copy</button></div><button class="btn primary" id="nativeShareUrl">Share URL</button><button class="btn light" id="openShareUrl">Open URL</button>`),input=$('#shareUrlValue');input.onclick=()=>input.select();$('#copyShareUrl').onclick=()=>copyShareUrl(url);$('#nativeShareUrl').onclick=async()=>{try{if(navigator.share)await navigator.share({title,text,url});else await copyShareUrl(url)}catch(error){if(error?.name!=='AbortError')await copyShareUrl(url)}};$('#openShareUrl').onclick=()=>window.open(url,'_blank','noopener,noreferrer');return box}
async function createSharedRouteUrl(route,title='Ridewise route'){if(!route)return null;try{const db=await getCloud(),payload={title,ownerId:S.user?.uid||null,payloadJson:JSON.stringify(route),createdAt:db.serverTimestamp()},ref=await db.addDoc(db.collection(db.firestore,'shared_routes_v1'),payload);return absoluteAppUrl({sharedRoute:ref.id})}catch(error){console.warn('Cloud route sharing unavailable',error);const compact={geometry:route.geometry,distance:route.distance,duration:route.duration,name:title};try{return absoluteAppUrl({routeData:btoa(unescape(encodeURIComponent(JSON.stringify(compact))))})}catch{return absoluteAppUrl()}}}
async function shareRouteObject(route,title='Ridewise route'){if(!route)return toast('Select a route first');toast('Creating share URL…');const url=await createSharedRouteUrl(route,title),description=`${fmt((route.distance||0)/1000)} km Ridewise cycling route`;showUrlShareWindow('Share route URL',url,description)}
async function shareRouteByIndex(index){const route=S.routes[index];if(!route)return toast('Select a route first');return shareRouteObject(route,route.savedName||route.name||`Ridewise route ${index+1}`)}
async function shareSavedRouteByIndex(index){const item=S.accountRoutes[index];if(!item?.route)return toast('Saved route unavailable');return shareRouteObject(item.route,item.name||'Saved Ridewise route')}
async function showLiveJourneyShare(){if(!S.liveJourney?.id)return toast('Start live navigation sharing first');const url=absoluteAppUrl({journey:S.liveJourney.id});showUrlShareWindow('Share live navigation URL',url,'Follow this live Ridewise journey')}
let resolveAuthReady;const authReady=new Promise(resolve=>{resolveAuthReady=resolve});
async function loadSharedRouteFromUrl(){const params=new URLSearchParams(location.search),id=params.get('sharedRoute'),inline=params.get('routeData');if((!id&&!inline)||S.sharedRouteLoaded||S.sharedRouteLoading)return;S.sharedRouteLoading=true;try{if(id){const user=await authReady;if(!user){S.sharedRouteLoading=false;open('profile');toast('Sign in to open this shared route URL');return}}let route;if(id){const db=await getCloud(),reference=db.doc(db.firestore,'shared_routes_v1',id),snapshot=await db.getDoc(reference);if(!snapshot.exists())throw new Error('Shared route not found');const data=snapshot.data();route=JSON.parse(data.payloadJson)}else route=JSON.parse(decodeURIComponent(escape(atob(inline))));if(!route?.geometry?.coordinates?.length)throw new Error('Invalid shared route');S.route=route;S.routes=[route];S.selected=0;S.mode='point';S.sharedRouteLoaded=true;clearLines();line('chosen',route.geometry,colors[0],8);open('explore');cards();updateQuickNav();toast('Shared route opened')}catch(error){console.error('Shared route open failed',error);if(error?.code==='permission-denied'){toast('Authentication is still restoring · retrying shared route');S.sharedRouteLoading=false;setTimeout(loadSharedRouteFromUrl,900);return}toast('Could not open shared route URL')}finally{if(S.sharedRouteLoaded||S.sharedRouteLoading)S.sharedRouteLoading=false}}

function createChoiceModal(title,body){document.querySelector('.share-choice,.map-location-menu')?.remove();const box=document.createElement('div');box.className='share-choice';box.innerHTML=`<button class="popup-close" aria-label="Close">×</button><b>${escapeHtml(title)}</b>${body}`;$('#map-wrap').appendChild(box);box.querySelector('.popup-close').onclick=()=>box.remove();return box}
function openMapShareMenu(){const box=createChoiceModal('Share URL','<p>Choose what the URL should open.</p><button id="shareCurrentRoute">Selected route URL</button><button id="shareProgress">Live navigation URL</button>');$('#shareCurrentRoute').onclick=async()=>{if(S.selected===null||!S.route)return toast('Select a route first');box.remove();await shareRouteByIndex(S.selected)};$('#shareProgress').onclick=async()=>{if(!S.route)return toast('Select a route first');if(!S.user){box.remove();open('profile');toast('Sign in to share live navigation');return}if(!S.record){const started=await startNavigation();if(started===false)return}if(!S.liveJourney)await startLiveJourney();box.remove();await showLiveJourneyShare()}}

function openGoogleMapsLocation(lngLat,threeD=false){const [lng,lat]=lngLat;if(!Number.isFinite(lat)||!Number.isFinite(lng))return toast('Invalid map location');const standard=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${lat},${lng}`)}`,threeDUrl=`https://www.google.com/maps/@${lat},${lng},250a,35y,0h,60t/data=!3m1!1e3`;const win=window.open(threeD?threeDUrl:standard,'_blank','noopener,noreferrer');if(!win)toast('Allow pop-ups to open Google Maps')}
function showMapLocationMenu(lngLat){document.querySelector('.map-location-menu')?.remove();const box=document.createElement('div');box.className='map-location-menu';box.innerHTML='<button class="popup-close" aria-label="Close">×</button><b>Use this location</b><button id="navigateHere">Navigate there</button><button id="addMapWaypoint">Add as waypoint</button><button id="googleMapView">View in Google Maps</button><button id="googleMap3d">View in Google Maps 3D</button><button id="copyMapCoordinates">Copy coordinates</button>';box.querySelector('.popup-close').onclick=()=>box.remove();$('#map-wrap').appendChild(box);const close=()=>box.remove();$('#navigateHere').onclick=async()=>{const start=S.pos||await current();if(!start)return;S.mode='point';S.waypoints=[start,lngLat];S.names=['Current location','Dropped pin'];await pointRoutes(false);open('explore');close()};$('#addMapWaypoint').onclick=()=>{if(S.mode==='loop'){S.adventureWaypoints.push({coord:lngLat,name:'Dropped pin'});toast('Adventure waypoint added')}else{if(S.waypoints.length<2)S.waypoints=[S.waypoints[0]||null,S.waypoints[1]||null];S.waypoints.splice(Math.max(1,S.waypoints.length-1),0,lngLat);S.names.splice(Math.max(1,S.names.length-1),0,'Dropped pin');toast('Waypoint added')}markers();close()};$('#googleMapView').onclick=()=>{openGoogleMapsLocation(lngLat,false);close()};$('#googleMap3d').onclick=()=>{openGoogleMapsLocation(lngLat,true);close()};$('#copyMapCoordinates').onclick=async()=>{const value=`${lngLat[1].toFixed(6)}, ${lngLat[0].toFixed(6)}`;try{await navigator.clipboard.writeText(value);toast('Coordinates copied')}catch{prompt('Copy coordinates',value)}close()}}
function installMapLocationGestures(){map.on('contextmenu',e=>showMapLocationMenu(e.lngLat.toArray()));let timer;map.getCanvas().addEventListener('touchstart',e=>{if(e.touches.length!==1)return;const t=e.touches[0];timer=setTimeout(()=>showMapLocationMenu(map.unproject([t.clientX,t.clientY]).toArray()),650)},{passive:true});['touchend','touchmove','touchcancel'].forEach(n=>map.getCanvas().addEventListener(n,()=>clearTimeout(timer),{passive:true}))}
const XWEATHER_ICON_BASE='https://cdn.aerisapi.com/wxblox/icons/';function weatherIconName(item){const raw=String(item?.icon||'').split('/').pop().toLowerCase();if(/^[a-z0-9_-]+\.png$/.test(raw))return raw;const d=String(item?.desc||'').toLowerCase(),night=new Date((item?.time||Date.now()/1000)*1000).getHours()<6||new Date((item?.time||Date.now()/1000)*1000).getHours()>=20,n=night?'n':'';if(/thunder/.test(d))return`tstorm${n}.png`;if(/snow|sleet|wintry/.test(d))return`snow${n}.png`;if(/shower/.test(d))return`showers${n}.png`;if(/rain|drizzle/.test(d))return`rain${n}.png`;if(/fog|mist|haze/.test(d))return`fog${n}.png`;if(/mostly cloudy/.test(d))return`mcloudy${n}.png`;if(/partly cloudy/.test(d))return`pcloudy${n}.png`;if(/cloud/.test(d))return`cloudy${n}.png`;return night?'clearn.png':'sunny.png'}function weatherIconUrl(item){return XWEATHER_ICON_BASE+weatherIconName(item)}function weatherMetric(icon,value,label,accent=''){return`<div class="weather-metric ${accent}"><span class="weather-metric-icon">${icon}</span><b>${value}</b><small>${label}</small></div>`}
function groupHourlyByDay(items=[]){const groups=new Map();for(const item of Array.isArray(items)?items:[]){if(!item||!Number.isFinite(Number(item.time)))continue;const date=new Date(Number(item.time)*1000),key=`${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;if(!groups.has(key))groups.set(key,{label:date.toLocaleDateString([],{weekday:'long',day:'numeric',month:'short'}),items:[]});groups.get(key).items.push(item)}return[...groups.values()].slice(0,4)}
async function weather(){if(!S.weather)await loadWeather();const w=S.weather;if(!w){panel.innerHTML=head('Weather','Current weather')+'<div class="empty">Weather unavailable</div>';return}const groups=groupHourlyByDay(S.hourlyWeather),rainNow=Math.round(S.hourlyWeather[0]?.probability||0);panel.innerHTML=head('Weather',`Live conditions from ${w.source}`)+`<div class="weather-hero card"><div class="weather-hero-main"><img src="${weatherIconUrl(w)}" alt="${escapeHtml(w.desc||'Weather')}" class="weather-main-icon"><div><span class="weather-kicker">NOW</span><h2>${Math.round(w.temp)}°C</h2><strong>${escapeHtml(w.desc||'Current conditions')}</strong><small>Feels like ${Math.round(w.feelsLike??w.temp)}°C</small></div></div><div class="weather-metrics">${weatherMetric('↗',cardinalDirection(w.bearing),'wind direction','wind')}${weatherMetric('≈',`${(w.speed*3.6).toFixed(1)} km/h`,'mean wind','wind')}${weatherMetric('≋',`${(w.gust*3.6).toFixed(1)} km/h`,'gust','gust')}${weatherMetric('💧',`${rainNow}%`,'rain chance','rain')}</div></div>${groups.map(day=>`<div class="weather-day card"><div class="weather-day-head"><div><span class="weather-kicker">FORECAST</span><h3>${day.label}</h3></div><span>${day.items.length} hours</span></div><div class="hourly weather-hourly">${day.items.map(x=>`<div class="hour weather-hour"><small class="weather-time">${new Date(x.time*1000).toLocaleTimeString([],{hour:'2-digit'})}</small><img src="${weatherIconUrl(x)}" alt="${escapeHtml(x.desc||'Weather')}" class="weather-hour-icon"><b>${Math.round(x.temp)}°</b><span>${escapeHtml(x.desc||'')}</span><small class="weather-wind"><i style="transform:rotate(${Number(x.bearing)||0}deg)">↑</i>${cardinalDirection(x.bearing)} ${(x.speed*3.6).toFixed(0)}</small><small class="weather-rain">💧 ${Math.round(x.probability||0)}%</small></div>`).join('')}</div></div>`).join('')}<button class="btn primary weather-map-button" id="toggleWind">${S.weatherOn?'Hide':'Show'} radar + wind</button>`;$('#toggleWind').onclick=toggleWeather}
async function loadWeather(){const p=map.getCenter(),[current,hourly]=await Promise.all([fetchWindAtLocation(p.lat,p.lng),fetchHourlyForecast(p.lat,p.lng,72)]);S.weather=current;S.hourlyWeather=hourly||[];if(current)S.wind={speed:current.speed*3.6,dir:current.bearing};await refreshWindGrid(true)}function icon(c){return c===0?'☀️':c<4?'⛅':c<70?'🌧️':c<80?'🌨️':'⛈️'}
async function toggleWeather(){S.weatherOn=!S.weatherOn;$('#weather').classList.toggle('active',S.weatherOn);if(S.weatherOn){if(!S.weather)await loadWeather();else await refreshWindGrid(true);await radar();windStart()}else{if(map.getLayer('radar'))map.removeLayer('radar');if(map.getSource('radar'))map.removeSource('radar');windStop()}if(S.page==='weather')weather()}
async function radar(){try{const d=await fetch('https://api.rainviewer.com/public/weather-maps.json').then(r=>r.json()),f=d.radar.past.at(-1);if(map.getLayer('radar'))map.removeLayer('radar');if(map.getSource('radar'))map.removeSource('radar');map.addSource('radar',{type:'raster',tiles:[`${d.host}${f.path}/512/{z}/{x}/{y}/2/1_1.png`],tileSize:512,maxzoom:7});map.addLayer({id:'radar',type:'raster',source:'radar',paint:{'raster-opacity':.3}})}catch{toast('Radar unavailable')}}
async function refreshWindGrid(force=false){if(S.windLoading)return;const b=map.getBounds(),zoom=map.getZoom(),cols=zoom<5?8:zoom<8?7:6,rows=zoom<5?6:zoom<8?5:4,key=[b.getWest().toFixed(1),b.getSouth().toFixed(1),b.getEast().toFixed(1),b.getNorth().toFixed(1),cols,rows].join('|');if(!force&&key===S.windGridKey)return;S.windLoading=true;try{const lats=[],lons=[];for(let y=0;y<rows;y++){const fy=y/(rows-1);for(let x=0;x<cols;x++){const fx=x/(cols-1);lons.push(wrapLng(b.getWest()+(b.getEast()-b.getWest())*fx));lats.push(b.getNorth()+(b.getSouth()-b.getNorth())*fy)}}const q=new URLSearchParams({latitude:lats.join(','),longitude:lons.join(','),current:'wind_speed_10m,wind_direction_10m'}),data=await fetch(`https://api.open-meteo.com/v1/forecast?${q}`).then(r=>r.json()),items=Array.isArray(data)?data:[data];S.windGrid={cols,rows,bounds:{west:b.getWest(),east:b.getEast(),south:b.getSouth(),north:b.getNorth()},cells:items.map((d,i)=>({speed:d?.current?.wind_speed_10m??S.wind.speed,dir:d?.current?.wind_direction_10m??S.wind.dir,lat:lats[i],lng:lons[i]}))};S.windGridKey=key}catch(e){console.warn('Spatial wind grid unavailable, using centre wind:',e);S.windGrid=null}finally{S.windLoading=false}}
function wrapLng(lng){return((lng+540)%360)-180}
function windAtScreen(x,y,width,height){const g=S.windGrid;if(!g?.cells?.length)return{speed:S.wind.speed,dir:S.wind.dir};const gx=Math.max(0,Math.min(g.cols-1,x/Math.max(1,width)*(g.cols-1))),gy=Math.max(0,Math.min(g.rows-1,y/Math.max(1,height)*(g.rows-1))),x0=Math.floor(gx),y0=Math.floor(gy),x1=Math.min(g.cols-1,x0+1),y1=Math.min(g.rows-1,y0+1),tx=gx-x0,ty=gy-y0,c00=g.cells[y0*g.cols+x0],c10=g.cells[y0*g.cols+x1],c01=g.cells[y1*g.cols+x0],c11=g.cells[y1*g.cols+x1];const vector=c=>{const a=((c.dir+180)%360)*Math.PI/180,s=Math.max(.1,c.speed);return{x:Math.sin(a)*s,y:-Math.cos(a)*s}},a=vector(c00),b=vector(c10),c=vector(c01),d=vector(c11),vx=(a.x*(1-tx)+b.x*tx)*(1-ty)+(c.x*(1-tx)+d.x*tx)*ty,vy=(a.y*(1-tx)+b.y*tx)*(1-ty)+(c.y*(1-tx)+d.y*tx)*ty;return{vx,vy,speed:Math.hypot(vx,vy)}}
let wf=0;function windStart(){const canvas=$('#wind'),ctx=canvas.getContext('2d'),wrap=$('#map-wrap'),d=devicePixelRatio||1;let rect=wrap.getBoundingClientRect();canvas.width=Math.round(rect.width*d);canvas.height=Math.round(rect.height*d);ctx.setTransform(d,0,0,d,0,0);canvas.style.display='block';const particles=Array.from({length:mobile()?180:340},()=>spawnWindParticle(rect));cancelAnimationFrame(wf);const draw=()=>{rect=wrap.getBoundingClientRect();ctx.clearRect(0,0,rect.width,rect.height);ctx.strokeStyle='rgba(70,210,255,.88)';ctx.lineWidth=1.05;for(const p of particles){const field=windAtScreen(p.x,p.y,rect.width,rect.height),mag=Math.max(.2,field.speed),scale=Math.max(.45,Math.min(2.8,mag/8)),vx=field.vx!==undefined?field.vx/mag*scale:Math.sin(((field.dir+180)%360)*Math.PI/180)*scale,vy=field.vy!==undefined?field.vy/mag*scale:-Math.cos(((field.dir+180)%360)*Math.PI/180)*scale,ox=p.x,oy=p.y;p.x+=vx;p.y+=vy;p.age++;ctx.beginPath();ctx.moveTo(ox-vx*5,oy-vy*5);ctx.lineTo(p.x,p.y);ctx.stroke();if(p.x<-25||p.y<-25||p.x>rect.width+25||p.y>rect.height+25||p.age>p.maxAge)Object.assign(p,spawnWindParticle(rect))}wf=requestAnimationFrame(draw)};draw()}
