async function requestScreenWakeLock(){S.wakeLockWanted=true;if(!('wakeLock'in navigator)){toast('Keep-screen-awake is unavailable on this browser');return false}if(document.visibilityState!=='visible')return false;if(S.wakeLock&&!S.wakeLock.released)return true;try{S.wakeLock=await navigator.wakeLock.request('screen');S.wakeLock.addEventListener('release',()=>{S.wakeLock=null;if(S.wakeLockWanted&&document.visibilityState==='visible')setTimeout(requestScreenWakeLock,500)});document.body.classList.add('wake-lock-active');return true}catch(e){console.warn('Screen wake lock was not granted:',e);document.body.classList.remove('wake-lock-active');toast('Could not keep the screen awake. Check Low Power Mode and browser permissions.');return false}}
async function releaseScreenWakeLock(){S.wakeLockWanted=false;document.body.classList.remove('wake-lock-active');if(S.wakeLock&&!S.wakeLock.released){try{await S.wakeLock.release()}catch(e){console.warn('Wake lock release failed',e)}}S.wakeLock=null}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.wakeLockWanted&&(S.record||S.navState))requestScreenWakeLock()});
async function current(){if(Array.isArray(S.pos))return S.pos;return new Promise(res=>navigator.geolocation.getCurrentPosition(p=>{S.pos=[p.coords.longitude,p.coords.latitude];res(S.pos)},()=>{const c=map?.getCenter?.();if(c){toast('Using map centre while GPS is unavailable');res([c.lng,c.lat])}else{toast('Allow location access');res(null)}},{enableHighAccuracy:false,maximumAge:300000,timeout:1800}))}$('#locate').onclick=async()=>{const p=await current();if(p){S.manualExploreUntil=0;if(S.navState)updateAdaptiveNavigationCamera(p,S.smoothedHeading,S.record?.speed||0,true);else map.flyTo({center:p,zoom:14})}};$('#weather').onclick=toggleWeather;$('#audio-nav').textContent=S.audioNavigation?'🔊':'🔇';$('#audio-nav').onclick=toggleAudioNavigation;$('#map-share').onclick=openMapShareMenu;document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='pause-recording')toggleRecordingPause();else if(id==='pause-navigation')toggleNavigationPause();else if(id==='end-recording')finishRecord(true);else if(id==='end-navigation')endNavigation()});$('#map-style').onclick=showMapStyles;function toggleCycleLayer(){S.cycleLayerOn=!S.cycleLayerOn;if(S.cycleLayerOn){if(!map.getSource('cyclosm'))map.addSource('cyclosm',{type:'raster',tiles:['https://a.tile-cyclosm.openstreetmap.fr/cyclosm-lite/{z}/{x}/{y}.png','https://b.tile-cyclosm.openstreetmap.fr/cyclosm-lite/{z}/{x}/{y}.png','https://c.tile-cyclosm.openstreetmap.fr/cyclosm-lite/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors · CyclOSM'});if(!map.getLayer('cyclosm'))map.addLayer({id:'cyclosm',type:'raster',source:'cyclosm',paint:{'raster-opacity':.72}})}else{if(map.getLayer('cyclosm'))map.removeLayer('cyclosm');if(map.getSource('cyclosm'))map.removeSource('cyclosm')}toast(S.cycleLayerOn?'Cycle infrastructure shown':'Cycle infrastructure hidden')}
function showMapStyles(){document.querySelector('.style-menu')?.remove();const menu=document.createElement('div');menu.className='style-menu';const styles=[['Outdoors','outdoors-v12'],['Streets','streets-v12'],['Satellite','satellite-streets-v12'],['Navigation day','navigation-day-v1'],['Navigation night','navigation-night-v1']];menu.innerHTML=styles.map(([n,id])=>`<button data-style="${id}">${n}</button>`).join('')+`<button id="toggleCycleLayer">${S.cycleLayerOn?'Hide':'Show'} cycle infrastructure</button><button class="popup-close" aria-label="Close">×</button>`;menu.querySelector('.popup-close').onclick=()=>menu.remove();menu.querySelector('#toggleCycleLayer').onclick=()=>{toggleCycleLayer();menu.remove()};$('#map-wrap').appendChild(menu);menu.onclick=e=>{const id=e.target.dataset.style;if(!id)return;map.setStyle(`mapbox://styles/mapbox/${id}`);map.once('style.load',()=>{if(S.selected===null&&S.routes.length)drawAll();else if(S.route){clearLines();line('chosen',S.route.geometry,colors[S.selected%colors.length],8)}if(S.weatherOn)radar();if(S.cycleLayerOn){S.cycleLayerOn=false;toggleCycleLayer()}});menu.remove()}}localStorage.removeItem('routes');localStorage.removeItem('activities');
map.on('load',()=>{installMapLocationGestures();open('explore');loadSharedRouteFromUrl();loadJourneyFromUrl();setTimeout(promptSessionRecovery,250)});map.on('dragstart',()=>{if(S.navState)S.manualExploreUntil=Date.now()+15000});map.on('zoomstart',()=>{if(S.navState)S.manualExploreUntil=Date.now()+15000});map.on('moveend',scheduleWindRefresh);map.on('zoomend',scheduleWindRefresh);addEventListener('resize',()=>{map.resize();if(S.weatherOn){refreshWindGrid(true).then(windStart)}});document.addEventListener('visibilitychange',()=>{if(document.hidden)persistActiveSession(true)});window.addEventListener('pagehide',()=>persistActiveSession(true));window.addEventListener('beforeunload',()=>persistActiveSession(true));window.addEventListener('online',updateOfflineNavigationStatus);window.addEventListener('offline',updateOfflineNavigationStatus);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.error);
